export const POST_RECIPIENTS={chinchilla:{name:'친칠라',role:'도서관 대출대 친구',replies:{hello:'산책하다 내 생각도 해 줬구나! 나는 오늘 책 사이에서 꽃잎 책갈피를 찾았어. 다음에 오면 네가 좋아할 만한 책을 같이 골라 보자.',thanks:'고맙다는 말을 들으니 나도 웃음이 나. 책을 찾다가 막히면 언제든 불러 줘. 우리 천천히 한 권씩 찾아가면 되니까.',discovery:'어떤 순간을 찾았을까? 나는 방금 햇빛에 반짝이는 책 표지를 발견했어. 평소 보던 것도 잠깐 멈춰 보면 새롭게 보이더라.'}},armadillo:{name:'아르마딜로',role:'책장 정리 친구',replies:{hello:'네 편지를 책갈피 옆에 살짝 세워 뒀어. 나는 책장을 정리하다가 잠깐 쉬는 중이야. 너도 산책하다 마음에 드는 자리가 보이면 앉아 쉬어 가.',thanks:'나도 네가 함께해 줘서 고마워. 오늘은 책 한 권을 제자리에 꽂았을 뿐인데, 네 편지 덕분에 그 작은 일도 소중하게 느껴져.',discovery:'작은 발견을 잊지 않으려고 나는 마음속에 이름을 붙여 봐. 오늘 찾은 건 ‘책장 사이 작은 무지개’야. 네가 찾은 순간에는 어떤 이름이 어울릴까?'}},capybara:{name:'카피바라',role:'창가에서 읽는 친구',replies:{hello:'햇볕 드는 창가에서 네 편지를 천천히 읽었어. 오늘 아무 일도 더 하지 않아도 괜찮아. 여기 빈자리에 앉아서 구름만 같이 봐도 좋겠어.',thanks:'마음을 전해 줘서 고마워. 나는 우리가 나란히 조용히 있던 순간도 좋아해. 꼭 멋진 말을 하지 않아도 함께 있는 마음은 전해지더라.',discovery:'나는 오늘 창문 그림자가 조금씩 움직이는 걸 봤어. 네가 좋아한 순간도 궁금하네. 다음에 만나면 하나씩 이야기해 보자. 서두르지 말고.'}}};
export const POST_TEMPLATES={hello:{label:'안부 한 줄',text:'오늘 마을을 산책했어. 너에게도 포근한 하루가 되었으면 좋겠어.'},thanks:{label:'고마운 마음',text:'함께해 줘서 고마워. 작은 순간들이 더 반짝였어.'},discovery:{label:'작은 발견',text:'오늘 좋아하는 순간을 하나 찾았어. 다음에 만나면 같이 이야기하자.'}};
export const postcardReply=letter=>POST_RECIPIENTS[letter?.recipient]?.replies[letter?.template]??'';
